import json, sys
data = json.loads(sys.stdin.read())
result = json.loads(data['result'])
exps = result['data']['experiments']

# Get details for experiments needing hypothesis
categories = {
    'mag_obsonly': [], 'mag_perdof': [], 'obs_only_seeds': [],
    'perdof_seeds': [], 'vla_only': [], 'argmin': [],
    'scalar': [], 'precompute': [], 'other': []
}

for k, v in exps.items():
    status = v.get('status', '')
    conclusion = v.get('conclusion', '')
    hypothesis = v.get('hypothesis', '')
    parent = v.get('parent', '')
    metrics = v.get('metrics', {})

    if (status == 'DONE' and conclusion in ('success', 'negative')) or status == 'RUNNING':
        if not hypothesis or len(str(hypothesis)) < 20:
            entry = {'id': k, 'status': status, 'conclusion': conclusion, 'parent': parent, 'metrics': str(metrics)[:100] if metrics else ''}
            if 'mag-obsonly' in k or 'mag_obsonly' in k:
                categories['mag_obsonly'].append(entry)
            elif 'mag-perdof' in k or 'mag_perdof' in k:
                categories['mag_perdof'].append(entry)
            elif 'obs-only' in k or 'obs_only' in k:
                categories['obs_only_seeds'].append(entry)
            elif 'perdof' in k:
                categories['perdof_seeds'].append(entry)
            elif 'vla' in k and ('only' in k or 'mean' in k):
                categories['vla_only'].append(entry)
            elif 'argmin' in k:
                categories['argmin'].append(entry)
            elif 'scalar' in k:
                categories['scalar'].append(entry)
            elif 'precompute' in k:
                categories['precompute'].append(entry)
            else:
                categories['other'].append(entry)

for cat, entries in categories.items():
    if entries:
        print(f'\n=== {cat} ({len(entries)} entries) ===')
        for e in entries[:5]:
            print(f\"  {e['id']}: {e['status']}/{e['conclusion']} parent={e['parent']} metrics={e['metrics'][:60]}\")
